#include "military_attack_damage_core.hpp"
#include "dynamic_land_strikes.hpp"
#include "resident/domains/travel/movement_exact_detail.hpp"
#include <algorithm>
#include <set>
#include <tuple>
namespace hanmo::resident {using namespace movement_detail;namespace {
DynamicLandStrikeFailure actual_failure(const RuleError& error){if(error.kind!=ErrorKind::rule)throw Failure{error};const auto& code=error.original.code;if(code=="MilitaryTargetUnavailable")return DynamicLandStrikeFailure::target_unavailable;if(code=="MilitaryFriendlyTarget")return DynamicLandStrikeFailure::friendly_target;if(code=="MilitaryTargetOutOfRange")return DynamicLandStrikeFailure::out_of_range;if(code=="MilitarySightBlocked")return DynamicLandStrikeFailure::sight_blocked;if(code=="MilitaryFlankNeedsMovement")return DynamicLandStrikeFailure::flank_needs_movement;if(code=="MilitaryFlankNeedsSideOrRear")return DynamicLandStrikeFailure::flank_needs_side_or_rear;throw Failure{error};}
Integer tactic_morale(const MilitaryBattleCatalog& c,const DynamicLandStrikeInput& input){if(input.tactic_id.empty())return 0;for(const auto& troop:c.troop_types)if(troop.id==input.original_attacker.troop_type_id)for(const auto& tactic:troop.tactics)if(tactic.id==input.tactic_id)return tactic.morale_effect;fail("DynamicMilitaryOriginalTacticRequired",input.tactic_id);}
void source_set(const std::vector<SourceRef>& refs,const char* code){if(refs.empty())fail(code);std::set<std::tuple<StableId,StableId,StableId>> unique;for(const auto& ref:refs)if(!source_valid(ref)||!unique.emplace(ref.domain,ref.kind,ref.id).second)fail(code,ref.id);}
}
Outcome<DynamicLandStrikeMerge> merge_dynamic_land_strikes(const MilitaryBattleCatalog& catalog,const std::vector<DynamicLandStrikeInput>& inputs,const std::vector<DynamicLandAllocationUnit>& units,const std::vector<DynamicLandQualifiedSupport>& supports,DynamicLandCasualtyRule rule,const DynamicMilitarySessionRandom& random,ExactArithmeticBudget budget){return guard<DynamicLandStrikeMerge>([&]{
 take(validate_dynamic_military_random_state(random));DynamicLandStrikeMerge out;out.rng_after=random;
 std::tuple<StableId,Integer,Integer> previous;bool first=true;std::set<std::tuple<StableId,StableId,StableId>> effects;
 // B: freeze every quote, including actual normal misses, without any draw.
 for(const auto& input:inputs){const auto key=std::make_tuple(input.original_attacker.unit_id,input.action_instance_ordinal,input.effect_ordinal);if(input.action_ref.empty()||input.action_instance_ordinal<0||input.effect_ordinal<0||input.original_damage_version!=1||!source_valid(input.effect_ref)||!effects.emplace(input.effect_ref.domain,input.effect_ref.kind,input.effect_ref.id).second||(!first&&key<=previous))fail("DynamicMilitaryCanonicalStrikeSetRequired",input.effect_ref.id);first=false;previous=key;
  if((input.original_damage_leaf==DynamicMilitaryDamageLeaf::commanded_factors)!=bool(input.actual_conditions.commanded)||(input.original_damage_leaf==DynamicMilitaryDamageLeaf::commanded_factors)!=(rule==DynamicLandCasualtyRule::commanded_factors))fail("DynamicMilitaryOriginalDamageLeafMismatch",input.effect_ref.id);
  if(input.original_damage_leaf!=DynamicMilitaryDamageLeaf::legacy_factors&&input.original_damage_leaf!=DynamicMilitaryDamageLeaf::commanded_factors)fail("DynamicMilitaryOriginalDamageLeafMismatch",input.effect_ref.id);
  source_set(input.original_precondition_sources,"DynamicMilitaryStrikePreconditionsRequired");source_set(input.original_geometry_sources,"DynamicMilitaryStrikeGeometryRequired");
  if(input.actual_release_source&&!source_valid(*input.actual_release_source))fail("DynamicMilitaryActualReleaseSourceRequired",input.effect_ref.id);
  for(const auto* snapshot:{&input.original_attacker,&input.original_target}){const auto unit=std::find_if(units.begin(),units.end(),[&](const auto& u){return u.unit_ref==snapshot->unit_id;});const bool released_shooter=snapshot==&input.original_attacker&&bool(input.actual_release_source);if(unit==units.end()||(!released_shooter&&(unit->original_fit_ids!=snapshot->fit||unit->original_morale!=snapshot->morale)))fail("DynamicMilitaryStrikeSnapshotChanged",snapshot->unit_id);}
  DynamicLandStrikeResult result;result.effect_ref=input.effect_ref;result.action_ref=input.action_ref;result.attacker_unit_ref=input.original_attacker.unit_id;result.target_unit_ref=input.original_target.unit_id;result.action_instance_ordinal=input.action_instance_ordinal;result.effect_ordinal=input.effect_ordinal;result.original_damage_leaf=input.original_damage_leaf;result.original_damage_version=input.original_damage_version;
  const auto quote=preview_dynamic_military_land_attack(input.original_attacker,input.original_target,catalog,input.battlefield_id,input.tactic_id,input.actual_geometry,input.actual_conditions,budget);if(!quote.ok)result.failure=actual_failure(quote.error);else{result.potential=quote.value.potential;result.chance=quote.value.hit_chance;result.flank_morale=quote.value.flank;result.tactic_morale=tactic_morale(catalog,input);if(result.potential<0||result.potential>500||result.chance<0||result.chance>100)fail("DynamicMilitaryOriginalQuoteOutOfRange",input.effect_ref.id);}
  out.strike_results.push_back(std::move(result));
 }
 // C: canonical original slots are assigned only after all B snapshots exist.
 for(auto& strike:out.strike_results){if(strike.failure!=DynamicLandStrikeFailure::none)continue;const auto expected=original_military_casualty_expectation(strike.potential,strike.chance);strike.raw=expected.minimum;if(strike.original_damage_leaf==DynamicMilitaryDamageLeaf::legacy_factors){auto slot=take(draw_dynamic_military_random_in_candidate(out.rng_after,strike.effect_ref,DynamicMilitaryRandomStage::strike,1,100));strike.raw=original_military_sampled_casualties(expected,slot.draw_result);strike.actual_random=slot;out.rng_slots.push_back(std::move(slot));}
  out.complete_strikes.push_back({strike.effect_ref,strike.action_ref,strike.attacker_unit_ref,strike.target_unit_ref,strike.action_instance_ordinal,strike.effect_ordinal,strike.raw,strike.flank_morale,strike.tactic_morale});
 }
 take(validate_dynamic_military_random_chain(random,out.rng_slots,out.rng_after));
 // D/E: one shared residual set, one classification/morale fold per unit.
 out.allocation=take(merge_dynamic_land_member_allocations(units,out.complete_strikes,supports,rule));return out;
});}
Status validate_dynamic_land_strikes(const MilitaryBattleCatalog& catalog,const std::vector<DynamicLandStrikeInput>& inputs,const std::vector<DynamicLandAllocationUnit>& units,const std::vector<DynamicLandQualifiedSupport>& supports,DynamicLandCasualtyRule rule,const DynamicMilitarySessionRandom& random,const DynamicLandStrikeMerge& saved,ExactArithmeticBudget budget){return status([&]{const auto expected=take(merge_dynamic_land_strikes(catalog,inputs,units,supports,rule,random,budget));if(saved.strike_results.size()!=expected.strike_results.size()||saved.rng_slots.size()!=expected.rng_slots.size()||saved.complete_strikes.size()!=expected.complete_strikes.size())fail("DynamicMilitaryStrikeGroupCoverageMismatch");
 for(std::size_t n=0;n<expected.strike_results.size();++n){const auto& a=expected.strike_results[n];const auto& b=saved.strike_results[n];if(!same_source(a.effect_ref,b.effect_ref)||a.action_ref!=b.action_ref||a.attacker_unit_ref!=b.attacker_unit_ref||a.target_unit_ref!=b.target_unit_ref||a.action_instance_ordinal!=b.action_instance_ordinal||a.effect_ordinal!=b.effect_ordinal||a.original_damage_leaf!=b.original_damage_leaf||a.original_damage_version!=b.original_damage_version||a.failure!=b.failure||a.raw!=b.raw||a.potential!=b.potential||a.chance!=b.chance||a.flank_morale!=b.flank_morale||a.tactic_morale!=b.tactic_morale||bool(a.actual_random)!=bool(b.actual_random)||(a.actual_random&&!same_dynamic_military_random_slot(*a.actual_random,*b.actual_random)))fail("DynamicMilitaryStrikeResultMismatch",b.effect_ref.id);}
 for(std::size_t n=0;n<expected.rng_slots.size();++n)if(!same_dynamic_military_random_slot(expected.rng_slots[n],saved.rng_slots[n]))fail("DynamicMilitaryStrikeRandomMismatch",saved.rng_slots[n].effect_ref.id);
 for(std::size_t n=0;n<expected.complete_strikes.size();++n){const auto& a=expected.complete_strikes[n];const auto& b=saved.complete_strikes[n];if(!same_source(a.effect_ref,b.effect_ref)||a.action_ref!=b.action_ref||a.attacker_unit_ref!=b.attacker_unit_ref||a.target_unit_ref!=b.target_unit_ref||a.action_instance_ordinal!=b.action_instance_ordinal||a.effect_ordinal!=b.effect_ordinal||a.raw_casualties!=b.raw_casualties||a.original_flank_morale!=b.original_flank_morale||a.original_tactic_morale!=b.original_tactic_morale)fail("DynamicMilitaryActualStrikeMismatch",b.effect_ref.id);}
 take(validate_dynamic_military_random_chain(random,saved.rng_slots,saved.rng_after));take(validate_dynamic_land_member_allocations(units,saved.complete_strikes,supports,rule,saved.allocation));
});}
}
